  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
];
let moveCount = 0;
let currentPlayer = "A";
let turnMoves = 0; // 0 or 1, each player gets 2 moves per turn
let gameOver = false;
let winner = null;

// connect the HTML + JS
cells.forEach((cell) => {
  cell.addEventListener("click", (event) => {
    const index = Number(event.currentTarget.dataset.index);
    onMove(index);
  });
});

function getRowCol(cellIndex) {
  return [Math.floor(cellIndex / 5), cellIndex % 5];
}

