  if (gameOver) return false;
  const [row, col] = getRowCol(cellIndex);
  if (board[row][col] !== "") return false;

  board[row][col] = currentPlayer;
  moveCount++;
  turnMoves++;

  // Check for win after each move
  if (checkWin(currentPlayer)) {
    gameOver = true;
    winner = currentPlayer;
  } else if (moveCount === 25) {
    gameOver = true;
    winner = null;
  }

  // Switch player after 2 moves
  if (turnMoves === 2 && !gameOver) {
    currentPlayer = currentPlayer === "A" ? "B" : "A";
    turnMoves = 0;
  }

  return true;
}

function checkWin(player) {
  // Check rows
  for (let r = 0; r < 5; r++) {
    let count = 0;
    for (let c = 0; c < 5; c++) {
      if (board[r][c] === player) {
        count++;
        if (count === 5) return true;
      } else {
        count = 0;
      }
    }
  }
  // Check columns
  for (let c = 0; c < 5; c++) {
    let count = 0;
    for (let r = 0; r < 5; r++) {
      if (board[r][c] === player) {
        count++;
        if (count === 5) return true;
      } else {
        count = 0;
      }
    }
  }
  return false;
}

function renderBoard() {
  for (let i = 0; i < 25; i++) {
    const [row, col] = getRowCol(i);
    cells[i].textContent = board[row][col];
    cells[i].disabled = board[row][col] !== "" || gameOver;
  }
  renderStatus();
}

function renderStatus() {
  if (gameOver) {
    if (winner === "A") {
      statusElement.textContent = "Status: Player A Wins!";
    } else if (winner === "B") {
      statusElement.textContent = "Status: Player B Wins!";
    } else {
      statusElement.textContent = "Status: Tie Game!";
    }
  } else {
    statusElement.textContent = `Status: Player ${currentPlayer} Turn`;
  }
}

function onMove(cellIndex) {
  if (playMove(cellIndex)) {
    renderBoard();
  }
}

// Initial render
renderBoard();

