css.content:
body {
  margin: 10px;
  display: flex;
  justify-content: center;
}

.board {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 4px;
}

.cell {
  min-width: 60px;
  min-height: 60px;
}

