// HTML elements
const cells = Array.from(document.querySelectorAll(".cell"));
const titleElement = document.querySelector(".title");

// global variables
let board = [
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
];
let currentPlayer = "X";
let gameOver = false;
let statusMessage = "Player X's turn";

// connect the HTML + JS
cells.forEach((cell) => {
  cell.addEventListener("click", (event) => {
    const index = Number(event.currentTarget.dataset.index);
    onMove(index);
  });
});

// JS functions

function playMove(cellIndex) {
  if (gameOver) return;

  const row = Math.floor(cellIndex / 5);
  const col = cellIndex % 5;

  if (board[row][col] !== "") {
    statusMessage = "Cell already taken! Try another.";
    return;
  }

  board[row][col] = currentPlayer;

  // Check for winner
  const winner = checkWinner();
  if (winner) {
    statusMessage = `Player ${winner} wins!`;
    gameOver = true;
    return;
  }

  // Check for draw
  if (isBoardFull()) {
    statusMessage = "It's a draw!";
    gameOver = true;
    return;
  }

  // Switch player
  currentPlayer = currentPlayer === "X" ? "O" : "X";
  statusMessage = `Player ${currentPlayer}'s turn`;
}

function renderBoard() {
  // Update cell text
  for (let i = 0; i < 25; i++) {
    const row = Math.floor(i / 5);
    const col = i % 5;
    cells[i].textContent = board[row][col];
    cells[i].disabled = gameOver || board[row][col] !== "";
  }

  // Update title/status
  if (titleElement) {
    titleElement.textContent = statusMessage;
  }
}

function onMove(cellIndex) {
  playMove(cellIndex);
  renderBoard();
}

// Helper functions

function checkWinner() {
  // Check rows
  for (let row = 0; row < 5; row++) {
    for (let col = 0; col <= 2; col++) {
      const mark = board[row][col];
      if (
        mark &&
        mark === board[row][col + 1] &&
        mark === board[row][col + 2]
      ) {
        return mark;
      }
    }
  }
  // Check columns
  for (let col = 0; col < 5; col++) {
    for (let row = 0; row <= 2; row++) {
      const mark = board[row][col];
      if (
        mark &&
        mark === board[row + 1][col] &&
        mark === board[row + 2][col]
      ) {
        return mark;
      }
    }
  }
  // Check diagonals (top-left to bottom-right)
  for (let row = 0; row <= 2; row++) {
    for (let col = 0; col <= 2; col++) {
      const mark = board[row][col];
      if (
        mark &&
        mark === board[row + 1][col + 1] &&
        mark === board[row + 2][col + 2]
      ) {
        return mark;
      }
    }
  }
  // Check diagonals (top-right to bottom-left)
  for (let row = 0; row <= 2; row++) {
    for (let col = 2; col < 5; col++) {
      const mark = board[row][col];
      if (
        mark &&
        mark === board[row + 1][col - 1] &&
        mark === board[row + 2][col - 2]
      ) {
        return mark;
      }
    }
  }
  return null;
}

function isBoardFull() {
  for (let row = 0; row < 5; row++) {
    for (let col = 0; col < 5; col++) {
      if (board[row][col] === "") {
        return false;
      }
    }
  }
  return true;
}

// Initial render
renderBoard();

