// HTML elements
const cells = Array.from(document.querySelectorAll(".cell"));
const titleElement = document.querySelector(".title");
const statusElement = document.getElementById("status");

// global variables
let board = [
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
];
let players = ["A", "B"];
let currentPlayerIndex = 0;
let movesThisTurn = 0; // 0 or 1, each player gets 2 moves per turn
let gameOver = false;
let statusMessage = "Status: Player A Turn";

// connect the HTML + JS
cells.forEach((cell) => {
  cell.addEventListener("click", (event) => {
    const index = Number(event.currentTarget.dataset.index);
    onMove(index);
  });
});

// JS functions

function playMove(cellIndex) {
  if (gameOver) return;

  const row = Math.floor(cellIndex / 5);
  const col = cellIndex % 5;

  if (board[row][col] !== "") {
    return;
  }

  const currentPlayer = players[currentPlayerIndex];
  board[row][col] = currentPlayer;

  // Check for winner
  const winner = checkWinner();
  if (winner) {
    statusMessage = winner === "A" ? "Status: Player A Wins!" : "Status: Player B Wins!";
    gameOver = true;
    return;
  }

  // Check for draw
  if (isBoardFull()) {
    statusMessage = "Status: Tie Game!";
    gameOver = true;
    return;
  }

  movesThisTurn += 1;
  if (movesThisTurn === 2) {
    // Switch player after 2 moves
    currentPlayerIndex = 1 - currentPlayerIndex;
    movesThisTurn = 0;
  }
  statusMessage = currentPlayerIndex === 0 ? "Status: Player A Turn" : "Status: Player B Turn";
}

function renderBoard() {
  // Update cell text
  for (let i = 0; i < 25; i++) {
    const row = Math.floor(i / 5);
    const col = i % 5;
    cells[i].textContent = board[row][col] === "A" ? "A" : (board[row][col] === "B" ? "B" : "");
    cells[i].disabled = gameOver || board[row][col] !== "";
  }

  // Update status
  if (statusElement) {
    statusElement.textContent = statusMessage;
  }
}

function onMove(cellIndex) {
  playMove(cellIndex);
  renderBoard();
}

/**
 * Check for 5 in a row horizontally or vertically (no diagonals).
 * Returns "A", "B", or null.
 */
function checkWinner() {
  // Check rows
  for (let row = 0; row < 5; row++) {
    let mark = board[row][0];
    if (mark && board[row].every(cell => cell === mark)) {
      return mark;
    }
  }
  // Check columns
  for (let col = 0; col < 5; col++) {
    let mark = board[0][col];
    if (mark && board.every(rowArr => rowArr[col] === mark)) {
      return mark;
    }
  }
  return null;
}

function isBoardFull() {
  for (let row = 0; row < 5; row++) {
    for (let col = 0; col < 5; col++) {
      if (board[row][col] === "") {
        return false;
      }
    }
  }
  return true;
}

// Initial render
renderBoard();

