// HTML elements
const cells = Array.from(document.querySelectorAll(".cell"));
// const statusElement = ...;

// global variables
let board = [
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
];
let currentPlayer = "A"; // Start with player A
let statusMessage = "";
let turnSymbolCount = 0; // Counts how many symbols placed in current turn (max 2)
let gameOver = false;

// connect the HTML + JS
cells.forEach((cell) => {
  cell.addEventListener("click", (event) => {
    const index = Number(event.currentTarget.dataset.index);
    onMove(index);
  });
});

// JS functions
function playMove(cellIndex) {
  if (gameOver) {
    statusMessage = "Game is over. Please refresh to play again.";
    return false;
  }

  // Convert cellIndex (0-24) to board coordinates
  const row = Math.floor(cellIndex / 5);
  const col = cellIndex % 5;

  // Only allow placing in empty cells
  if (board[row][col] !== "") {
    statusMessage = "Cell already taken!";
    return false; // Indicate move was not successful
  }

  // Place the current player's symbol (lowercase for display)
  board[row][col] = currentPlayer === "A" ? "a" : "b";
  turnSymbolCount++;

  // Check for win after this move
  if (checkWin(row, col)) {
    statusMessage = `Player ${currentPlayer} wins!`;
    gameOver = true;
    return true;
  }

  // Check for tie (no empty cells left)
  if (isBoardFull()) {
    statusMessage = "Tie game!";
    gameOver = true;
    return true;
  }

  // After two symbols, switch player
  if (turnSymbolCount >= 2) {
    currentPlayer = currentPlayer === "A" ? "B" : "A";
    turnSymbolCount = 0;
  }

  statusMessage = `Player ${currentPlayer}'s turn`;
  return true; // Indicate move was successful
}

// Check for five in a row horizontally or vertically (not diagonally)
function checkWin(row, col) {
  const symbol = board[row][col];
  // Horizontal check
  let count = 0;
  for (let c = 0; c < 5; c++) {
    if (board[row][c] === symbol) {
      count++;
      if (count === 5) return true;
    } else {
      count = 0;
    }
  }
  // Vertical check
  count = 0;
  for (let r = 0; r < 5; r++) {
    if (board[r][col] === symbol) {
      count++;
      if (count === 5) return true;
    } else {
      count = 0;
    }
  }
  return false;
}

// Check if the board is full (tie)
function isBoardFull() {
  for (let r = 0; r < 5; r++) {
    for (let c = 0; c < 5; c++) {
      if (board[r][c] === "") {
        return false;
      }
    }
  }
  return true;
}

function renderBoard() {
  // Update the board display
  cells.forEach((cell, idx) => {
    const row = Math.floor(idx / 5);
    const col = idx % 5;
    cell.textContent = board[row][col];
  });

  // Optionally, display status message somewhere
  // For now, log to console
  console.log(statusMessage);
}

function onMove(cellIndex) {
  const moved = playMove(cellIndex);
  renderBoard();
}

