// HTML elements
const cells = Array.from(document.querySelectorAll(".cell"));
const turnIndicator = document.getElementById("turn-indicator");
// const statusElement = ...;

// global variables
let board = [
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
];
let currentPlayer = "A";
let statusMessage = "";
let placementsThisTurn = 0;
const placementsPerTurn = 2;
let gameOver = false;

function initialRender() {
  renderBoard();
}

// connect the HTML + JS
cells.forEach((cell) => {
  cell.addEventListener("click", (event) => {
    const index = Number(event.currentTarget.dataset.index);
    onMove(index);
  });
});

initialRender();

// JS functions
function playMove(cellIndex) {
  console.log("User clicked on cell:", cellIndex);

  if (gameOver) {
    return;
  }

  // Convert cellIndex (0-24) to row and col
  const row = Math.floor(cellIndex / 5);
  const col = cellIndex % 5;

  // If the cell is already filled, do nothing
  if (board[row][col] !== "") {
    return;
  }

  // Set the cell to the current player
  board[row][col] = currentPlayer;

  // Increment placements for this turn
  placementsThisTurn += 1;

  // Check for win after the move
  const winner = checkWinner();
  if (winner) {
    statusMessage = `Player ${winner} wins!`;
    gameOver = true;
    return;
  }

  // Check for tie
  if (isBoardFull()) {
    statusMessage = "Tie game";
    gameOver = true;
    return;
  }

  // If player has placed twice, switch player and reset counter
  if (placementsThisTurn >= placementsPerTurn) {
    currentPlayer = currentPlayer === "A" ? "B" : "A";
    placementsThisTurn = 0;
  }
}

function renderBoard() {
  console.log("Displaying the board");
  // Update the UI to reflect the board state
  cells.forEach((cell, idx) => {
    const row = Math.floor(idx / 5);
    const col = idx % 5;
    cell.textContent = board[row][col];
    // Optionally, disable the cell if filled or game is over
    cell.disabled = board[row][col] !== "" || gameOver;
  });

  // Update the turn indicator or show winner/tie
  if (turnIndicator) {
    if (gameOver) {
      turnIndicator.textContent = statusMessage;
    } else {
      const remaining = placementsPerTurn - placementsThisTurn;
      turnIndicator.textContent = `Player ${currentPlayer}'s turn (${remaining} placement${remaining === 1 ? '' : 's'} left)`;
    }
  }
}

function onMove(cellIndex) {
  playMove(cellIndex);
  renderBoard();
}

// Check for 5 in a row or column for either player
function checkWinner() {
  // Check rows
  for (let row = 0; row < 5; row++) {
    const first = board[row][0];
    if (first && board[row].every(cell => cell === first)) {
      return first;
    }
  }
  // Check columns
  for (let col = 0; col < 5; col++) {
    const first = board[0][col];
    if (first && [0,1,2,3,4].every(row => board[row][col] === first)) {
      return first;
    }
  }
  return null;
}

// Check if the board is full
function isBoardFull() {
  for (let row = 0; row < 5; row++) {
    for (let col = 0; col < 5; col++) {
      if (board[row][col] === "") {
        return false;
      }
    }
  }
  return true;
}

