// HTML elements
const cells = Array.from(document.querySelectorAll(".cell"));
// const statusElement = ...;

// global variables
let board = [
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
];
let currentPlayer = "a";
let statusMessage = "";
let movesThisTurn = 0;
let gameOver = false;

// connect the HTML + JS
cells.forEach((cell) => {
  cell.addEventListener("click", (event) => {
    const index = Number(event.currentTarget.dataset.index);
    onMove(index);
  });
});

// JS functions
function playMove(cellIndex) {
  console.log("User clicked on cell:", cellIndex);

  if (gameOver) {
    statusMessage = "Game is over!";
    return;
  }

  // Convert cellIndex (0-24) to board coordinates
  const row = Math.floor(cellIndex / 5);
  const col = cellIndex % 5;

  // Only allow placing in empty cells
  if (board[row][col] !== "") {
    statusMessage = "Cell already taken!";
    return;
  }

  // Place the current player's symbol
  board[row][col] = currentPlayer;
  movesThisTurn += 1;

  // Check for win or tie after the move
  if (checkWin(currentPlayer)) {
    statusMessage = `Player ${currentPlayer.toUpperCase()} wins!`;
    gameOver = true;
    return;
  } else if (isBoardFull()) {
    statusMessage = "It's a tie!";
    gameOver = true;
    return;
  }

  // After two moves, switch player
  if (movesThisTurn >= 2) {
    currentPlayer = currentPlayer === "a" ? "b" : "a";
    movesThisTurn = 0;
  }
  statusMessage = `Player ${currentPlayer.toUpperCase()}'s turn`;
}

function renderBoard() {
  console.log("Displaying the board");
  // Update the UI to reflect the board state
  for (let i = 0; i < 25; i++) {
    const row = Math.floor(i / 5);
    const col = i % 5;
    cells[i].textContent = board[row][col];
  }
  // Optionally display status message somewhere
  // For now, show in document title
  document.title = statusMessage;
}

function onMove(cellIndex) {
  playMove(cellIndex);
  renderBoard();
}

// Check for five in a row horizontally or vertically (not diagonally)
function checkWin(player) {
  // Check rows
  for (let row = 0; row < 5; row++) {
    let win = true;
    for (let col = 0; col < 5; col++) {
      if (board[row][col] !== player) {
        win = false;
        break;
      }
    }
    if (win) return true;
  }
  // Check columns
  for (let col = 0; col < 5; col++) {
    let win = true;
    for (let row = 0; row < 5; row++) {
      if (board[row][col] !== player) {
        win = false;
        break;
      }
    }
    if (win) return true;
  }
  // No diagonal win
  return false;
}

// Check if the board is full (tie)
function isBoardFull() {
  for (let row = 0; row < 5; row++) {
    for (let col = 0; col < 5; col++) {
      if (board[row][col] === "") {
        return false;
      }
    }
  }
  return true;
}

