const cells = Array.from(document.querySelectorAll(".cell"));
// const statusElement = ...;

// global variables
let board = [
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
];
let currentPlayer = "A";
let symbolsPlacedThisTurn = 0;
let statusMessage = "";

// connect the HTML + JS
cells.forEach((cell) => {
  cell.addEventListener("click", (event) => {
    const index = Number(event.currentTarget.dataset.index);
    onMove(index);
  });
});

// JS functions
function playMove(cellIndex) {
  console.log("User clicked on cell:", cellIndex);

  // Convert cellIndex (0-24) to row,col
  const row = Math.floor(cellIndex / 5);
  const col = cellIndex % 5;

  // Only allow placing in empty cells
  if (board[row][col] !== "") {
    statusMessage = "Cell already taken!";
    return;
  }

  // Place the current player's symbol
  board[row][col] = currentPlayer;
  symbolsPlacedThisTurn++;

  // After two placements, switch player
  if (symbolsPlacedThisTurn >= 2) {
    currentPlayer = currentPlayer === "A" ? "B" : "A";
    symbolsPlacedThisTurn = 0;
  }
  statusMessage = `Player ${currentPlayer}'s turn.`;
}

function renderBoard() {
  console.log("Displaying the board");
  // Render the board state to the HTML buttons
  for (let i = 0; i < 25; i++) {
    const row = Math.floor(i / 5);
    const col = i % 5;
    cells[i].textContent = board[row][col];
  }
  // Optionally display status somewhere
  // Example: document.getElementById("status").textContent = statusMessage;
}

function onMove(cellIndex) {
  playMove(cellIndex);
  renderBoard();
}

