// HTML elements
const cells = Array.from(document.querySelectorAll(".cell"));
// const statusElement = ...;

// global variables
let board = [
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
];
let currentPlayer = "A";
let symbolsPlacedThisTurn = 0;
let statusMessage = "";
let gameOver = false;

// connect the HTML + JS
cells.forEach((cell) => {
  cell.addEventListener("click", (event) => {
    const index = Number(event.currentTarget.dataset.index);
    onMove(index);
  });
});

// JS functions
function playMove(cellIndex) {
  console.log("User clicked on cell:", cellIndex);

  if (gameOver) {
    statusMessage = "Game is over. Please refresh to play again.";
    return false;
  }

  // Convert cellIndex (0-24) to row,col
  const row = Math.floor(cellIndex / 5);
  const col = cellIndex % 5;

  // Only allow placing in empty cells
  if (board[row][col] !== "") {
    statusMessage = "Cell already taken!";
    return false; // indicate move was not successful
  }

  // Place the current player's symbol
  board[row][col] = currentPlayer;
  symbolsPlacedThisTurn++;

  // Check for win after move
  if (checkWin(currentPlayer)) {
    statusMessage = `Player ${currentPlayer} wins!`;
    gameOver = true;
    return true;
  }

  // Check for tie (no empty cells left)
  if (isBoardFull()) {
    statusMessage = "It's a tie!";
    gameOver = true;
    return true;
  }

  // After two placements, switch player
  if (symbolsPlacedThisTurn >= 2) {
    currentPlayer = currentPlayer === "A" ? "B" : "A";
    symbolsPlacedThisTurn = 0;
  }
  statusMessage = `Player ${currentPlayer}'s turn.`;
  return true; // indicate move was successful
}

function renderBoard() {
  console.log("Displaying the board");
  // Render the board state to the HTML buttons
  for (let i = 0; i < 25; i++) {
    const row = Math.floor(i / 5);
    const col = i % 5;
    cells[i].textContent = board[row][col];
  }
  // Optionally display status somewhere
  // Example: document.getElementById("status").textContent = statusMessage;
}

function onMove(cellIndex) {
  const moveSuccess = playMove(cellIndex);
  renderBoard();
}

// Check for five in a row horizontally or vertically for the given player
function checkWin(player) {
  // Check rows
  for (let row = 0; row < 5; row++) {
    let count = 0;
    for (let col = 0; col < 5; col++) {
      if (board[row][col] === player) {
        count++;
      } else {
        break;
      }
    }
    if (count === 5) return true;
  }
  // Check columns
  for (let col = 0; col < 5; col++) {
    let count = 0;
    for (let row = 0; row < 5; row++) {
      if (board[row][col] === player) {
        count++;
      } else {
        break;
      }
    }
    if (count === 5) return true;
  }
  return false;
}

// Check if the board is full (tie)
function isBoardFull() {
  for (let row = 0; row < 5; row++) {
    for (let col = 0; col < 5; col++) {
      if (board[row][col] === "") {
        return false;
      }
    }
  }
  return true;
}

