  if (gameState !== "playing") {
    return;
  }

  // Convert cellIndex (0-24) to row and col
  const row = Math.floor(cellIndex / 5);
  const col = cellIndex % 5;

  // Only allow move if cell is empty
  if (board[row][col] === "") {
    board[row][col] = currentPlayer;

    // Check for win or tie after the move
    const winner = checkWinner();
    if (winner === "A") {
      gameState = "A_wins";
    } else if (winner === "B") {
      gameState = "B_wins";
    } else if (isBoardFull()) {
      gameState = "tie";
    }

    // Switch player only if game is still playing
    if (gameState === "playing") {
      currentPlayer = currentPlayer === "A" ? "B" : "A";
    }
  }
}

function renderBoard() {
  console.log("Displaying the board");
  // Update each cell's text content based on the board state
  cells.forEach((cell, idx) => {
    const row = Math.floor(idx / 5);
    const col = idx % 5;
    cell.textContent = board[row][col];
  });

  // Update the status message
  if (statusElement) {
    if (gameState === "A_wins") {
      statusElement.textContent = "Player A Wins!";
    } else if (gameState === "B_wins") {
      statusElement.textContent = "Player B Wins!";
    } else if (gameState === "tie") {
      statusElement.textContent = "Tie Game!";
    } else {
      statusElement.textContent = `Player ${currentPlayer} Turn`;
    }
  }
}

function onMove(cellIndex) {
  playMove(cellIndex);
  renderBoard();
}

// Check for five in a row horizontally or vertically
function checkWinner() {
  // Check rows
  for (let row = 0; row < 5; row++) {
    let first = board[row][0];
    if (first !== "" && board[row].every(cell => cell === first)) {
      return first;
    }
  }
  // Check columns
  for (let col = 0; col < 5; col++) {
    let first = board[0][col];
    if (first !== "" && [0,1,2,3,4].every(row => board[row][col] === first)) {
      return first;
    }
  }
  return null;
}

// Check if the board is full (no empty cells)
function isBoardFull() {
  for (let row = 0; row < 5; row++) {
    for (let col = 0; col < 5; col++) {
      if (board[row][col] === "") {
        return false;
      }
    }
  }
  return true;
}

