// HTML elements
const cells = Array.from(document.querySelectorAll(".cell"));
// const statusElement = ...;

// global variables
let board = [
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
];
let currentPlayer = "A";
let statusMessage = "Status: Player A Turn";
let playerMoveCount = 0; // Counts moves for current player (max 2 before switching)

// connect the HTML + JS
cells.forEach((cell) => {
  cell.addEventListener("click", (event) => {
    const index = Number(event.currentTarget.dataset.index);
    onMove(index);
  });
});

// JS functions
function playMove(cellIndex) {
  console.log("User clicked on cell:", cellIndex);

  // Convert cellIndex (0-24) to row,col
  const row = Math.floor(cellIndex / 5);
  const col = cellIndex % 5;

  // Ignore if cell is already filled or game is over
  if (board[row][col] !== "" || gameOver()) {
    return;
  }

  // Place symbol for current player
  board[row][col] = currentPlayer;

  // Increment move count for this player
  playerMoveCount += 1;

  // Update the cell visually
  cells[cellIndex].textContent = currentPlayer;

  // Check for win or tie
  if (checkWin(currentPlayer)) {
    statusMessage = `Status: Player ${currentPlayer} Wins!`;
    return;
  } else if (isBoardFull()) {
    statusMessage = "Status: Tie Game!";
    return;
  }

  // After two moves, switch player
  if (playerMoveCount === 2) {
    currentPlayer = currentPlayer === "A" ? "B" : "A";
    playerMoveCount = 0;
  }

  statusMessage = `Status: Player ${currentPlayer} Turn`;
}

function renderBoard() {
  console.log("Displaying the board");
  // Update the status element
  const statusElement = document.getElementById("status");
  if (statusElement) {
    statusElement.textContent = statusMessage;
  }
}

// Check if the current player has 5 in a row horizontally or vertically
function checkWin(player) {
  // Check rows
  for (let row = 0; row < 5; row++) {
    let win = true;
    for (let col = 0; col < 5; col++) {
      if (board[row][col] !== player) {
        win = false;
        break;
      }
    }
    if (win) return true;
  }
  // Check columns
  for (let col = 0; col < 5; col++) {
    let win = true;
    for (let row = 0; row < 5; row++) {
      if (board[row][col] !== player) {
        win = false;
        break;
      }
    }
    if (win) return true;
  }
  return false;
}

// Check if the board is full (tie)
function isBoardFull() {
  for (let row = 0; row < 5; row++) {
    for (let col = 0; col < 5; col++) {
      if (board[row][col] === "") {
        return false;
      }
    }
  }
  return true;
}

// Check if the game is over (win or tie)
function gameOver() {
  return checkWin("A") || checkWin("B") || isBoardFull();
}

function onMove(cellIndex) {
  playMove(cellIndex);
  renderBoard();
}

