// global variables
let board = [
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
];
// Turn system: A->A->B->B->A->A...
let currentPlayer = "A";
let movesThisTurn = 0; // 0 or 1, after 2 moves switch player
let statusMessage = "";
let gameOver = false;

// connect the HTML + JS
cells.forEach((cell) => {
  cell.addEventListener("click", (event) => {
    const index = Number(event.currentTarget.dataset.index);
    onMove(index);
  });
});

// JS functions
function playMove(cellIndex) {
  if (gameOver) {
    return;
  }
  console.log("User clicked on cell:", cellIndex);

  // Convert cellIndex (0-24) to row,col
  const row = Math.floor(cellIndex / 5);
  const col = cellIndex % 5;

  // Only allow placing in empty cells
  if (board[row][col] !== "") {
    statusMessage = "Cell already taken!";
    return;
  }

  // Place current player's symbol
  board[row][col] = currentPlayer;

  // Check for win after placing
  const winner = checkWinner();
  if (winner) {
    statusMessage = `Player ${winner} wins!`;
    gameOver = true;
    return;
  }

  movesThisTurn += 1;

  if (movesThisTurn >= 2) {
    // Switch player after 2 moves
    currentPlayer = currentPlayer === "A" ? "B" : "A";
    movesThisTurn = 0;
  }

  statusMessage = `Player ${currentPlayer}'s turn (${movesThisTurn + 1}/2)`;
}

function renderBoard() {
  // Update the board UI
  for (let i = 0; i < 25; i++) {
    const row = Math.floor(i / 5);
    const col = i % 5;
    cells[i].textContent = board[row][col];
