js.content:
// HTML elements
const cells = Array.from(document.querySelectorAll(".cell"));
const statusElement = document.getElementById("status");

// global variables
let board = [
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
];
let currentPlayer = "A";
let turnCount = 0; // counts turns for current player (max 2)
let gameOver = false;
let winner = null;

// connect the HTML + JS
cells.forEach((cell) => {
  cell.addEventListener("click", (event) => {
    const index = Number(event.currentTarget.dataset.index);
    onMove(index);
  });
});

// JS functions

function playMove(cellIndex) {
  if (gameOver) return false;
  const row = Math.floor(cellIndex / 5);
  const col = cellIndex % 5;
  if (board[row][col] !== "") {
    return false; // already filled
  }
  board[row][col] = currentPlayer;
  turnCount += 1;
  // Check for win
  if (checkWin(currentPlayer)) {
    winner = currentPlayer;
    gameOver = true;
  } else if (turnCount === 2) {
    // Switch player after 2 turns
    currentPlayer = currentPlayer === "A" ? "B" : "A";
    turnCount = 0;
  }
  return true;
}

function checkWin(player) {
  // Check rows
  for (let r = 0; r < 5; r++) {
    if (board[r].every(cell => cell === player)) return true;
  }
  // Check columns
  for (let c = 0; c < 5; c++) {
    let colWin = true;
    for (let r = 0; r < 5; r++) {
      if (board[r][c] !== player) {
        colWin = false;
        break;
      }
    }
    if (colWin) return true;
  }
  // Check diagonals
  let diag1 = true, diag2 = true;
  for (let i = 0; i < 5; i++) {
    if (board[i][i] !== player) diag1 = false;
    if (board[i][4 - i] !== player) diag2 = false;
  }
  return diag1 || diag2;
}

function renderBoard() {
  // Update cell text
  for (let i = 0; i < 25; i++) {
    const row = Math.floor(i / 5);
    const col = i % 5;
    cells[i].textContent = board[row][col];
    cells[i].disabled = board[row][col] !== "" || gameOver;
    cells[i].style.cursor = (board[row][col] === "" && !gameOver) ? "pointer" : "not-allowed";
  }
  // Update status
  if (winner) {
    statusElement.textContent = `Player ${winner} wins!`;
  } else if (gameOver) {
    statusElement.textContent = "Game over!";
  } else {
    statusElement.textContent = `Player ${currentPlayer}'s turn (${turnCount + 1}/2)`;
  }
}

function onMove(cellIndex) {
  if (gameOver) return;
  const moved = playMove(cellIndex);
  renderBoard();
}

// Initial render
renderBoard();

