// HTML elements
const cells = Array.from(document.querySelectorAll(".cell"));
// const statusElement = ...;

// global variables
let board = [
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
];
let currentPlayer = "A"; // Start with player A
let turnSymbolCount = 0; // Counts how many symbols placed in current turn (max 2)
let statusMessage = "";

// connect the HTML + JS
cells.forEach((cell) => {
  cell.addEventListener("click", (event) => {
    const index = Number(event.currentTarget.dataset.index);
    onMove(index);
  });
});

// JS functions
function playMove(cellIndex) {
  console.log("User clicked on cell:", cellIndex);

  // Convert cellIndex (0-24) to board coordinates
  const row = Math.floor(cellIndex / 5);
  const col = cellIndex % 5;

  // Ignore if cell is already filled
  if (board[row][col] !== "") {
    statusMessage = "Cell already filled!";
    return;
  }

  // Place current player's symbol
  board[row][col] = currentPlayer;
  turnSymbolCount += 1;

  // After 2 moves, switch player
  if (turnSymbolCount === 2) {
    currentPlayer = currentPlayer === "A" ? "B" : "A";
    turnSymbolCount = 0;
  }

  statusMessage = `Player ${currentPlayer}'s turn.`;
}

function renderBoard() {
  console.log("Displaying the board");
  // Update the UI to reflect the board state
  cells.forEach((cell, idx) => {
    const row = Math.floor(idx / 5);
    const col = idx % 5;
    cell.textContent = board[row][col];
  });

  // Optionally display status somewhere
  // For now, log to console
  console.log(statusMessage);
}

function onMove(cellIndex) {
  playMove(cellIndex);
  renderBoard();
}

