// HTML elements
const cells = Array.from(document.querySelectorAll(".cell"));
const statusElement = document.getElementById("status");

// global variables
let board = [
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
];
let currentPlayer = "A";
let movesThisTurn = 0;
let isGameOver = false;
let statusMessage = "";

// connect the HTML + JS
cells.forEach((cell) => {
  cell.addEventListener("click", (event) => {
    const index = Number(event.currentTarget.dataset.index);
    onMove(index);
  });
});

function checkWin(player) {
  for(let r = 0 ; r<5 ; r++){
    if(board[r].every(cell => cell === player))return true;
  }
  for(let c =0 ; c<5;c++){
    let colWin = true;
    for(let r=0;r<5;r++){
      if(board[r][c] !== player)colWin = false;
    }
    if(colWin) return true;
  }
  return false;
}

function checkTie(){
  return board.every(row => row.every(cell => cell!== ""));
}

// JS functions
function playMove(cellIndex) {
  if(isGameOver)return;
  const row = Math.floor(cellIndex/5);
  const col = cellIndex % 5;
  if(board[row][col] !== "")return;
  board[row][col] = currentPlayer;
  movesThisTurn++;

  if(checkWin(currentPlayer)){
    statusElement.textContent = `Status: Player ${currentPlayer} Wins!`
  }
  console.log("User clicked on cell:", cellIndex);
}

function renderBoard() {
  console.log("Displaying the board");
}

function onMove(cellIndex) {
  playMove(cellIndex);
  renderBoard();
}

