const cells = Array.from(document.querySelectorAll(".cell"));
const statusElement = document.getElementById("status");

// global variables
let board = [
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
];
let currentPlayer = "A";
let movesThisTurn = 0;
let statusMessage = "";

// connect the HTML + JS
cells.forEach((cell) => {
  cell.addEventListener("click", (event) => {
    const index = Number(event.currentTarget.dataset.index);
    onMove(index);
  });
});

// JS functions
function playMove(cellIndex) {
  // Convert cellIndex (0-24) to row,col
  const row = Math.floor(cellIndex / 5);
  const col = cellIndex % 5;
  console.log(`Player ${currentPlayer} clicked on cell: (${row}, ${col}) [index ${cellIndex}]`);

  // Ignore if cell is already filled
  if (board[row][col] !== "") {
    // Do not count this as a move
    return;
  }

  // Mark the cell for the current player
  board[row][col] = currentPlayer;
  movesThisTurn += 1;

  // Check for win after every move
  if (checkWin(currentPlayer)) {
    statusMessage = `Status: Player ${currentPlayer} wins!`;
    renderBoard();
    updateStatus();
    // Optionally, you could disable further moves here
    return;
  }

  // Check for tie (no empty cells left)
  if (isBoardFull()) {
    statusMessage = "Status: Tie";
    renderBoard();
    updateStatus();
    return;
  }

  // After two moves, switch player
  if (movesThisTurn >= 2) {
    currentPlayer = currentPlayer === "A" ? "B" : "A";
    movesThisTurn = 0;
  }
}

function renderBoard() {
  // Update the UI to reflect the board state
  for (let i = 0; i < 25; i++) {
    const row = Math.floor(i / 5);
    const col = i % 5;
    cells[i].textContent = board[row][col];
  }
}

function updateStatus() {
  if (statusElement) {
    if (statusMessage) {
      statusElement.textContent = statusMessage;
    } else {
      statusElement.textContent = `Status: Player ${currentPlayer}'s turn`;
    }
  }
}

// Only allow moves if game is not over
function onMove(cellIndex) {
  if (statusMessage.startsWith("Status: Player") || statusMessage === "Status: Tie") {
    // Game is over, do not allow further moves
    return;
  }
  playMove(cellIndex);
  renderBoard();
  updateStatus();
}

/**
 * Check for 5 consecutive in a row or column (not diagonal)
 */
function checkWin(player) {
  // Check rows
  for (let row = 0; row < 5; row++) {
    let count = 0;
    for (let col = 0; col < 5; col++) {
      if (board[row][col] === player) {
        count++;
      } else {
        break;
      }
    }
    if (count === 5) {
      return true;
    }
  }

  // Check columns
  for (let col = 0; col < 5; col++) {
    let count = 0;
    for (let row = 0; row < 5; row++) {
      if (board[row][col] === player) {
        count++;
      } else {
        break;
      }
    }
    if (count === 5) {
      return true;
    }
  }

  // No win found
  return false;
}

/**
 * Returns true if the board is full (no empty cells)
 */
function isBoardFull() {
  for (let row = 0; row < 5; row++) {
    for (let col = 0; col < 5; col++) {
      if (board[row][col] === "") {
        return false;
      }
    }
  }
  return true;
}

