function playMove(cellIndex) {
  if (gameOver) return;

  console.log("User clicked on cell:", cellIndex);

  // Convert cellIndex (0-24) to board coordinates
  const row = Math.floor(cellIndex / 5);
  const col = cellIndex % 5;

  // If the cell is already filled, do nothing
  if (board[row][col] !== "") {
    return;
  }

  // Hidden turn tracker logic
  currentPlayer = getCurrentPlayer();

  // Mark the board with the current player
  board[row][col] = currentPlayer;

  // Check for win condition
  if (checkFiveInARow(currentPlayer)) {
    gameOver = true;
    statusMessage = `Player ${currentPlayer} wins!`;
  } else if (isBoardFull()) {
    gameOver = true;
    statusMessage = "Board is full. No winner!";
  }

  // Advance the turn counter for next move
  turnCounter++;
}

