const cells = Array.from(document.querySelectorAll(".cell"));
const statusElement = document.getElementById("status-message");

/*
Implements alternating turns between player A and player B.
Each player can place two symbols per turn.
Start with player A.
*/

let board = [
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
];
let currentPlayer = "A";
let placedThisTurn = 0; // counts how many symbols placed in current turn (max 2)
let statusMessage = "";
let gameOver = false;

// Set initial status message
statusElement.textContent = "Status: Player A turn";

// connect the HTML + JS
cells.forEach((cell) => {
  cell.addEventListener("click", (event) => {
    const index = Number(event.currentTarget.dataset.index);
    onMove(index);
  });
});

function checkWinner() {
  // Check rows
  for (let row = 0; row < 5; row++) {
    let first = board[row][0];
    if (first && board[row].every(cell => cell === first)) {
      return first;
    }
  }
  // Check columns
  for (let col = 0; col < 5; col++) {
    let first = board[0][col];
    if (first && [0,1,2,3,4].every(row => board[row][col] === first)) {
      return first;
    }
  }
  return null;
}

function isBoardFull() {
  return board.every(row => row.every(cell => cell !== ""));
}

// JS functions
function playMove(cellIndex) {
  if (gameOver) return;
  console.log("User clicked on cell:", cellIndex);

  // Convert cellIndex (0-24) to row,col
  const row = Math.floor(cellIndex / 5);
  const col = cellIndex % 5;

  // Only allow placing if cell is empty and player has not placed 2 symbols this turn
  if (board[row][col] === "" && placedThisTurn < 2) {
    board[row][col] = currentPlayer;
    placedThisTurn += 1;

    // Update the cell visually
    cells[cellIndex].textContent = currentPlayer;

    // Check for winner after each move
    const winner = checkWinner();
    if (winner) {
      statusMessage = `Player ${winner} wins!`;
      gameOver = true;
      renderBoard();
      return;
    } else if (isBoardFull()) {
      statusMessage = "It's a tie!";
      gameOver = true;
      renderBoard();
      return;
    }

    // If player has placed 2 symbols, switch turn
    if (placedThisTurn === 2) {
      currentPlayer = currentPlayer === "A" ? "B" : "A";
      placedThisTurn = 0;
    }
  }
}

function renderBoard() {
  console.log("Displaying the board");
  // Update all cells to match board state
  for (let i = 0; i < 25; i++) {
    const row = Math.floor(i / 5);
    const col = i % 5;
    cells[i].textContent = board[row][col];
    cells[i].disabled = !!board[row][col] || gameOver;
  }
  // Update status message
  if (gameOver) {
    statusElement.textContent = (
      statusMessage === "It's a tie!"
        ? "Status: Tie Game!"
        : "Status: " + statusMessage.replace(" wins!", " Wins!")
    );
  } else {
    statusElement.textContent = `Status: Player ${currentPlayer} turn`;
  }
}

function onMove(cellIndex) {
  playMove(cellIndex);
  renderBoard();
}

