  if (checkWin(row, col, currentPlayer)) {
    gameOver = true;
    winner = currentPlayer;
  } else if (isBoardFull()) {
    gameOver = true;
    winner = null;
  } else if (movesThisTurn === 2) {
    // Switch player after 2 moves
    currentPlayer = currentPlayer === "A" ? "B" : "A";
    movesThisTurn = 0;
  }

  return true;
}

function renderBoard() {
  // Update the board UI
  for (let i = 0; i < 25; i++) {
    const row = Math.floor(i / 5);
    const col = i % 5;
    cells[i].textContent = board[row][col];
    cells[i].disabled = !!board[row][col] || gameOver;
  }

  // Update status
  if (gameOver) {
    if (winner === "A") {
      statusElement.textContent = "Status: Player A wins!";
    } else if (winner === "B") {
      statusElement.textContent = "Status: Player B wins!";
    } else {
      statusElement.textContent = "Status: Tie game!";
    }
  } else {
    statusElement.textContent = `Status: Player ${currentPlayer} Turn`;
  }
}

function onMove(cellIndex) {
  const moved = playMove(cellIndex);
  renderBoard();
}

